import{_ as E,I as i,c as n,o as e,a3 as a,b as o,w as l,a as s,J as d,a4 as A}from"./chunks/framework.Cc9k46oU.js";const D=JSON.parse('{"title":"高リスク作業の多段階承認および監査証跡ガイド","description":"エージェントによるデータ変更およびデプロイ作業に対するリスクレベル別の多者順次承認 (HITL) および監査ログの運用手順","frontmatter":{"title":"高リスク作業の多段階承認および監査証跡ガイド","shortTitle":"多段階承認 & 監査","category":"運用ガイド","sort":2,"description":"エージェントによるデータ変更およびデプロイ作業に対するリスクレベル別の多者順次承認 (HITL) および監査ログの運用手順","head":[["link",{"rel":"canonical","href":"https://doc.empasy.com/ja/guide/hitl-approval-operations"}],["link",{"rel":"alternate","hreflang":"ko","href":"https://doc.empasy.com/guide/hitl-approval-operations"}],["link",{"rel":"alternate","hreflang":"en","href":"https://doc.empasy.com/en/guide/hitl-approval-operations"}],["link",{"rel":"alternate","hreflang":"ja","href":"https://doc.empasy.com/ja/guide/hitl-approval-operations"}],["link",{"rel":"alternate","hreflang":"x-default","href":"https://doc.empasy.com/guide/hitl-approval-operations"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:site_name","content":"Empasy Docs"}],["meta",{"property":"og:title","content":"高リスク作業の多段階承認および監査証跡ガイド | Empasy Docs"}],["meta",{"property":"og:description","content":"エージェントによるデータ変更およびデプロイ作業に対するリスクレベル別の多者順次承認 (HITL) および監査ログの運用手順"}],["meta",{"property":"og:url","content":"https://doc.empasy.com/ja/guide/hitl-approval-operations"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"高リスク作業の多段階承認および監査証跡ガイド | Empasy Docs"}],["meta",{"name":"twitter:description","content":"エージェントによるデータ変更およびデプロイ作業に対するリスクレベル別の多者順次承認 (HITL) および監査ログの運用手順"}]]},"headers":[],"relativePath":"ja/guide/hitl-approval-operations.md","filePath":"ja/guide/hitl-approval-operations.md","lastUpdated":1795293539000}'),p={name:"ja/guide/hitl-approval-operations.md"};function g(h,t,c,m,B,_){const r=i("Mermaid");return e(),n("div",null,[t[1]||(t[1]=a('<h1 id="高リスク作業の多段階承認および監査証跡ガイド" tabindex="-1">高リスク作業の多段階承認および監査証跡ガイド <a class="header-anchor" href="#高リスク作業の多段階承認および監査証跡ガイド" aria-label="Permalink to “高リスク作業の多段階承認および監査証跡ガイド”">​</a></h1><h2 id="_1-作業リスクレベル分類基準-risk-levels" tabindex="-1">1. 作業リスクレベル分類基準 (Risk Levels) <a class="header-anchor" href="#_1-作業リスクレベル分類基準-risk-levels" aria-label="Permalink to “1. 作業リスクレベル分類基準 (Risk Levels)”">​</a></h2><p>エージェントが呼び出すすべてのツール (Tool) およびビジネスアクションは、システムに与える影響度に応じて4段階のリスクレベルに事前分類されて管理されます。</p><table tabindex="0"><thead><tr><th style="text-align:center;">レベル</th><th style="text-align:left;">作業種別</th><th style="text-align:left;">対象作業の例</th><th style="text-align:left;">承認ポリシー</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>Level 1 (安全)</strong></td><td style="text-align:left;">単純照会およびレポーティング</td><td style="text-align:left;">注文状況の照会、ログ検索、RAG ドキュメント探索</td><td style="text-align:left;"><strong>無承認での自律実行</strong> (実行履歴を自動記録)</td></tr><tr><td style="text-align:center;"><strong>Level 2 (注意)</strong></td><td style="text-align:left;">可逆的な設定変更</td><td style="text-align:left;">クローリング周期の変更、キャッシュ有効期限設定、通知チャネル設定</td><td style="text-align:left;"><strong>単一担当者による承認</strong> (1名承認)</td></tr><tr><td style="text-align:center;"><strong>Level 3 (警告)</strong></td><td style="text-align:left;">データ変更および削除</td><td style="text-align:left;">会員情報の修正、商品価格の一括変更、DBレコード削除</td><td style="text-align:left;"><strong>2段階順次承認</strong> (担当者 -&gt; 部門長)</td></tr><tr><td style="text-align:center;"><strong>Level 4 (危険)</strong></td><td style="text-align:left;">システム全体への影響</td><td style="text-align:left;">本番環境への新規バージョンデプロイ、DDL スキーマ変更、大量返金</td><td style="text-align:left;"><strong>3段階多者承認</strong> (担当者 -&gt; CISO -&gt; 責任者)</td></tr></tbody></table><hr><h2 id="_2-webコンソール承認画面の操作手順" tabindex="-1">2. Webコンソール承認画面の操作手順 <a class="header-anchor" href="#_2-webコンソール承認画面の操作手順" aria-label="Permalink to “2. Webコンソール承認画面の操作手順”">​</a></h2><p>Level 2 以上の作業が検知されると、エージェントの実行が即座に一時停止 (PAUSED) され、管理ポータルの承認待ち一覧にカードが登録されます。</p>',7)),(e(),o(A,null,{default:l(()=>[d(r,{id:"mermaid-92",class:"mermaid",graph:"stateDiagram-v2%0A%20%20%20%20%5B*%5D%20--%3E%20PENDING_APPROVAL%3A%20%E9%AB%98%E3%83%AA%E3%82%B9%E3%82%AF%E4%BD%9C%E6%A5%AD%E3%83%84%E3%83%BC%E3%83%AB%E5%91%BC%E3%81%B3%E5%87%BA%E3%81%97%0A%20%20%20%20PENDING_APPROVAL%20--%3E%20IN_REVIEW%3A%20%E7%AE%A1%E7%90%86%E8%80%85%E8%A9%B3%E7%B4%B0%E7%94%BB%E9%9D%A2%E3%81%AE%E7%85%A7%E4%BC%9A%0A%20%20%20%20IN_REVIEW%20--%3E%20APPROVED%3A%201%E6%AC%A1%2F2%E6%AC%A1%E6%89%BF%E8%AA%8D%E5%AE%8C%E4%BA%86%0A%20%20%20%20IN_REVIEW%20--%3E%20REJECTED%3A%20%E5%8D%B4%E4%B8%8B%E6%B1%BA%E5%AE%9A%0A%20%20%20%20IN_REVIEW%20--%3E%20AMENDMENT_REQUESTED%3A%20%E6%9D%A1%E4%BB%B6%E4%BB%98%E3%81%8D%E4%BF%AE%E6%AD%A3%E6%8C%87%E7%A4%BA%0A%20%20%20%20APPROVED%20--%3E%20EXECUTED%3A%20%E3%83%90%E3%83%83%E3%82%AF%E3%82%A8%E3%83%B3%E3%83%89%E5%AE%89%E5%85%A8%E5%AE%9F%E8%A1%8C%E3%81%8A%E3%82%88%E3%81%B3%E3%82%B9%E3%83%8A%E3%83%83%E3%83%97%E3%82%B7%E3%83%A7%E3%83%83%E3%83%88%E4%BF%9D%E7%AE%A1%0A%20%20%20%20REJECTED%20--%3E%20CANCELLED%3A%20%E4%BD%9C%E6%A5%AD%E3%82%AD%E3%83%A3%E3%83%B3%E3%82%BB%E3%83%AB%E3%81%8A%E3%82%88%E3%81%B3%E8%A3%9C%E5%84%9F%E3%83%AD%E3%83%BC%E3%83%AB%E3%83%90%E3%83%83%E3%82%AF%0A%20%20%20%20AMENDMENT_REQUESTED%20--%3E%20PENDING_APPROVAL%3A%20%E3%82%A8%E3%83%BC%E3%82%B8%E3%82%A7%E3%83%B3%E3%83%88%E3%83%91%E3%83%A9%E3%83%A1%E3%83%BC%E3%82%BF%E4%BF%AE%E6%AD%A3%E5%BE%8C%E3%81%AE%E5%86%8D%E6%8F%90%E5%87%BA%0A"})]),fallback:l(()=>[...t[0]||(t[0]=[s(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<h3 id="段階別の確認項目" tabindex="-1">段階別の確認項目 <a class="header-anchor" href="#段階別の確認項目" aria-label="Permalink to “段階別の確認項目”">​</a></h3><ol><li><strong>影響範囲 (Blast Radius) の確認</strong>: <ul><li>変更対象のテーブル名、変更予定のレコード件数 (Row Count) を確認します。</li><li>単一レコードではなく1,000件以上の大量変更案件である場合、理由が妥当であるかを精査します。</li></ul></li><li><strong>変更前後の Diff 照合</strong>: <ul><li>変更前 (Current State) と変更後 (Proposed State) の JSON/SQL データの差分が正確であることを確認します。</li></ul></li><li><strong>ロールバックスナップショットの可用性検証</strong>: <ul><li>システム障害発生時に以前の状態へ戻せるスナップショットIDが正常に生成されているか、インジケータを点検します。</li></ul></li></ol><hr><h2 id="_3-管理者意思決定アクションガイド" tabindex="-1">3. 管理者意思決定アクションガイド <a class="header-anchor" href="#_3-管理者意思決定アクションガイド" aria-label="Permalink to “3. 管理者意思決定アクションガイド”">​</a></h2><ul><li><strong>承認 (Approve)</strong>: <ul><li>確認の結果、作業内容に問題がない場合は「承認」ボタンをクリックします。</li><li>多者承認案件の場合は次の承認権限者へ承認ルートが順次引き継がれ、最終承認時に実際のトランザクションがコミットされます。</li></ul></li><li><strong>却下 (Reject)</strong>: <ul><li>ビジネスポリシーに違反している場合やデータ汚染の懸念がある場合は、具体的な却下理由を入力して作業を拒否します。</li><li>エージェントは即座に作業を中断し、関連リソースを解放します。</li></ul></li><li><strong>修正指示 (Amend)</strong>: <ul><li>方向性は妥当であるものの、パラメータ (例: 価格割引率、対象ユーザー範囲など) の微調整が必要な場合は、修正フィードバックを記述してエージェントに再作業を指示できます。</li></ul></li></ul><hr><h2 id="_4-監査ログの追跡および改ざん防止" tabindex="-1">4. 監査ログの追跡および改ざん防止 <a class="header-anchor" href="#_4-監査ログの追跡および改ざん防止" aria-label="Permalink to “4. 監査ログの追跡および改ざん防止”">​</a></h2><p>すべての承認/却下の意思決定履歴は、内部監査台帳 (Audit Ledger) に永続保存されます:</p><ul><li><strong>記録項目</strong>: リクエスト日時、実行エージェントID、承認者社員番号およびIPアドレス、リクエスト元のプロンプト、ツールパラメータのハッシュ値、最終実行結果。</li><li><strong>完全性保証</strong>: 監査ログはタイムスタンプに基づく暗号化ハッシュチェーン (SHA-256) で相互に結合されているため、データベース管理者であっても過去の履歴を任意に操作したり削除したりすることはできません。</li></ul>',9))])}const u=E(p,[["render",g]]);export{D as __pageData,u as default};
